/**
 * Lazy fixture creation - only creates fixtures when requested and caches them
 * Works with transaction rollback for automatic cleanup
 * @param {Object} test - Mocha test context
 * @param {string} type - Type of fixture to create ('user', 'testPlan', 'planSection', 'cases', etc.)
 * @param {Object} overrides - Override values for fixture creation
 * @param {number} overrides.count - Number of items to create (for 'cases' type)
 * @returns {Promise<Object>} Cached or newly created fixture
 */
async function getFixture(test, type, overrides = {}) {
    const key = `${type}_${JSON.stringify(overrides)}`;
    if (!test._fixtures[key]) {
        const transaction = test.db || test.transaction;

        // Ensure transaction is always passed through
        const fixtureOverrides = { ...overrides, transaction };

        switch (type) {
            case 'user':
                test._fixtures[key] = await generateFakeUserWithTeam(fixtureOverrides);
                break;
            case 'userWithRole':
                test._fixtures[key] = await generateFakeUserWithTeamAndRole(fixtureOverrides);
                break;
            case 'testPlan':
                test._fixtures[key] = await createTestPlanWithDependencies(fixtureOverrides);
                break;
            case 'planSection':
                test._fixtures[key] = await createPlanSectionWithDependencies(fixtureOverrides);
                break;
            case 'cases':
                const count = overrides.count || 2;
                test._fixtures[key] = await createCasesWithDependencies(count, fixtureOverrides);
                break;
            case 'daaAttributeReporting':
                test._fixtures[key] =
                    await generateFakeDaaAttributeReportingWithDependencies(fixtureOverrides);
                break;
            default:
                throw new Error(`Unknown fixture type: ${type}`);
        }
    }
    return test._fixtures[key];
}

