        generateHMACSignature(timestamp, body, secret).should.equal(`sha256=${expected}`);
    });

    it('Should return the same signature when called with the same inputs', function () {
        const first = generateHMACSignature(timestamp, body, secret);
        const second = generateHMACSignature(timestamp, body, secret);
        first.should.equal(second);
    });

    it('Should return a different signature when the timestamp changes', function () {
        const sig1 = generateHMACSignature(timestamp, body, secret);
        const sig2 = generateHMACSignature(timestamp + 1, body, secret);
        sig1.should.not.equal(sig2);
    });

    it('Should return a different signature when the body changes', function () {
